ALTER TYPE "CaseCategory" ADD VALUE IF NOT EXISTS 'FARMING';
ALTER TYPE "CaseCategory" ADD VALUE IF NOT EXISTS 'ELDERLY';
ALTER TYPE "CaseCategory" ADD VALUE IF NOT EXISTS 'HOUSING';
ALTER TYPE "CaseCategory" ADD VALUE IF NOT EXISTS 'WATER';
ALTER TYPE "CaseCategory" ADD VALUE IF NOT EXISTS 'DISABILITY';
ALTER TYPE "CaseCategory" ADD VALUE IF NOT EXISTS 'EMERGENCY';
ALTER TYPE "CaseCategory" ADD VALUE IF NOT EXISTS 'COMMUNITY';
ALTER TYPE "CaseCategory" ADD VALUE IF NOT EXISTS 'FOOD';
ALTER TYPE "CaseCategory" ADD VALUE IF NOT EXISTS 'OTHER';
CREATE TYPE "VerificationStatus" AS ENUM ('PENDING','IN_REVIEW','VERIFIED','REJECTED','NEEDS_MORE_EVIDENCE');
CREATE TYPE "OfferType" AS ENUM ('MONEY','GOODS','SKILLS','TIME','TRANSPORT','ACCOMMODATION','SERVICES','OTHER');
CREATE TYPE "ThreadStatus" AS ENUM ('OPEN','CLOSED');
CREATE TYPE "NotificationType" AS ENUM ('SECURITY','CASE','MESSAGE','VERIFICATION','PAYMENT','SYSTEM');
CREATE TYPE "ReportType" AS ENUM ('FRAUD','HARASSMENT','SCAM','SAFEGUARDING','OTHER');
CREATE TYPE "TransactionStatus" AS ENUM ('CREATED','PROCESSING','SUCCEEDED','FAILED','REFUNDED');
CREATE TYPE "FraudSignalStatus" AS ENUM ('OPEN','REVIEWED','DISMISSED','CONFIRMED');
ALTER TABLE "User" ALTER COLUMN "status" SET DEFAULT 'PENDING';
ALTER TABLE "User" ADD COLUMN IF NOT EXISTS "emailVerifiedAt" TIMESTAMP(3), ADD COLUMN IF NOT EXISTS "mfaEnabled" BOOLEAN NOT NULL DEFAULT false, ADD COLUMN IF NOT EXISTS "mfaSecretEncrypted" TEXT, ADD COLUMN IF NOT EXISTS "failedLoginCount" INTEGER NOT NULL DEFAULT 0, ADD COLUMN IF NOT EXISTS "lockedUntil" TIMESTAMP(3);
ALTER TABLE "HelpCase" ADD COLUMN IF NOT EXISTS "verificationStatus" "VerificationStatus" NOT NULL DEFAULT 'PENDING', ADD COLUMN IF NOT EXISTS "verificationSummary" TEXT;
CREATE TABLE IF NOT EXISTS "Referral" ("id" TEXT NOT NULL,"referrerId" TEXT NOT NULL,"personName" TEXT NOT NULL,"needSummary" TEXT NOT NULL,"safeContact" TEXT,"consentConfirmed" BOOLEAN NOT NULL,"status" TEXT NOT NULL DEFAULT 'PENDING_CONTACT',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "Referral_pkey" PRIMARY KEY ("id"));
CREATE INDEX IF NOT EXISTS "Referral_referrerId_createdAt_idx" ON "Referral"("referrerId","createdAt");
CREATE TABLE IF NOT EXISTS "CaseEvidence" ("id" TEXT NOT NULL,"caseId" TEXT NOT NULL,"type" TEXT NOT NULL,"storageKey" TEXT NOT NULL,"sha256" TEXT NOT NULL,"mimeType" TEXT NOT NULL,"sizeBytes" INTEGER NOT NULL,"uploadedBy" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "CaseEvidence_pkey" PRIMARY KEY ("id"));
CREATE INDEX IF NOT EXISTS "CaseEvidence_caseId_idx" ON "CaseEvidence"("caseId");
CREATE TABLE IF NOT EXISTS "VerificationRequest" ("id" TEXT NOT NULL,"caseId" TEXT NOT NULL,"requesterId" TEXT NOT NULL,"status" "VerificationStatus" NOT NULL DEFAULT 'PENDING',"reason" TEXT,"reviewerId" TEXT,"reviewedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "VerificationRequest_pkey" PRIMARY KEY ("id"));
CREATE INDEX IF NOT EXISTS "VerificationRequest_status_createdAt_idx" ON "VerificationRequest"("status","createdAt"); CREATE INDEX IF NOT EXISTS "VerificationRequest_caseId_idx" ON "VerificationRequest"("caseId");
CREATE TABLE IF NOT EXISTS "HelpOffer" ("id" TEXT NOT NULL,"userId" TEXT NOT NULL,"caseId" TEXT,"type" "OfferType" NOT NULL,"title" TEXT NOT NULL,"description" TEXT NOT NULL,"amountMinor" INTEGER,"currency" TEXT,"countryCode" TEXT NOT NULL,"status" TEXT NOT NULL DEFAULT 'ACTIVE',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "HelpOffer_pkey" PRIMARY KEY ("id"));
CREATE INDEX IF NOT EXISTS "HelpOffer_countryCode_status_idx" ON "HelpOffer"("countryCode","status"); CREATE INDEX IF NOT EXISTS "HelpOffer_caseId_idx" ON "HelpOffer"("caseId");
CREATE TABLE IF NOT EXISTS "MessageThread" ("id" TEXT NOT NULL,"caseId" TEXT,"status" "ThreadStatus" NOT NULL DEFAULT 'OPEN',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "MessageThread_pkey" PRIMARY KEY ("id"));
CREATE INDEX IF NOT EXISTS "MessageThread_caseId_idx" ON "MessageThread"("caseId");
CREATE TABLE IF NOT EXISTS "Message" ("id" TEXT NOT NULL,"threadId" TEXT NOT NULL,"senderId" TEXT NOT NULL,"body" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "Message_pkey" PRIMARY KEY ("id"));
CREATE INDEX IF NOT EXISTS "Message_threadId_createdAt_idx" ON "Message"("threadId","createdAt");
CREATE TABLE IF NOT EXISTS "_ThreadParticipants" ("A" TEXT NOT NULL,"B" TEXT NOT NULL); CREATE UNIQUE INDEX IF NOT EXISTS "_ThreadParticipants_AB_unique" ON "_ThreadParticipants"("A","B"); CREATE INDEX IF NOT EXISTS "_ThreadParticipants_B_idx" ON "_ThreadParticipants"("B");
CREATE TABLE IF NOT EXISTS "Report" ("id" TEXT NOT NULL,"reporterId" TEXT NOT NULL,"caseId" TEXT,"type" "ReportType" NOT NULL,"description" TEXT NOT NULL,"status" TEXT NOT NULL DEFAULT 'OPEN',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "Report_pkey" PRIMARY KEY ("id")); CREATE INDEX IF NOT EXISTS "Report_status_createdAt_idx" ON "Report"("status","createdAt");
CREATE TABLE IF NOT EXISTS "Notification" ("id" TEXT NOT NULL,"userId" TEXT NOT NULL,"type" "NotificationType" NOT NULL,"title" TEXT NOT NULL,"body" TEXT NOT NULL,"readAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "Notification_pkey" PRIMARY KEY ("id")); CREATE INDEX IF NOT EXISTS "Notification_userId_readAt_createdAt_idx" ON "Notification"("userId","readAt","createdAt");
CREATE TABLE IF NOT EXISTS "EmailVerificationToken" ("id" TEXT NOT NULL,"userId" TEXT NOT NULL,"tokenHash" TEXT NOT NULL,"expiresAt" TIMESTAMP(3) NOT NULL,"usedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "EmailVerificationToken_pkey" PRIMARY KEY ("id")); CREATE UNIQUE INDEX IF NOT EXISTS "EmailVerificationToken_tokenHash_key" ON "EmailVerificationToken"("tokenHash"); CREATE INDEX IF NOT EXISTS "EmailVerificationToken_userId_expiresAt_idx" ON "EmailVerificationToken"("userId","expiresAt");
CREATE TABLE IF NOT EXISTS "PasswordResetToken" ("id" TEXT NOT NULL,"userId" TEXT NOT NULL,"tokenHash" TEXT NOT NULL,"expiresAt" TIMESTAMP(3) NOT NULL,"usedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "PasswordResetToken_pkey" PRIMARY KEY ("id")); 

CREATE UNIQUE INDEX IF NOT EXISTS "PasswordResetToken_tokenHash_key" ON "PasswordResetToken"("tokenHash"); CREATE INDEX IF NOT EXISTS "PasswordResetToken_userId_expiresAt_idx" ON "PasswordResetToken"("userId","expiresAt");
CREATE TABLE IF NOT EXISTS "Transaction" ("id" TEXT NOT NULL,"userId" TEXT NOT NULL,"caseId" TEXT NOT NULL,"amountMinor" INTEGER NOT NULL,"currency" TEXT NOT NULL,"purpose" TEXT,"status" "TransactionStatus" NOT NULL DEFAULT 'CREATED',"providerReference" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Transaction_pkey" PRIMARY KEY ("id")); CREATE UNIQUE INDEX IF NOT EXISTS "Transaction_providerReference_key" ON "Transaction"("providerReference"); CREATE INDEX IF NOT EXISTS "Transaction_userId_createdAt_idx" ON "Transaction"("userId","createdAt"); CREATE INDEX IF NOT EXISTS "Transaction_caseId_status_createdAt_idx" ON "Transaction"("caseId","status","createdAt");
CREATE TABLE IF NOT EXISTS "FraudSignal" ("id" TEXT NOT NULL,"caseId" TEXT NOT NULL,"actorId" TEXT,"type" TEXT NOT NULL,"severity" TEXT NOT NULL,"status" "FraudSignalStatus" NOT NULL DEFAULT 'OPEN',"details" JSONB,"resolutionNote" TEXT,"resolvedBy" TEXT,"resolvedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "FraudSignal_pkey" PRIMARY KEY ("id")); CREATE INDEX IF NOT EXISTS "FraudSignal_status_severity_createdAt_idx" ON "FraudSignal"("status","severity","createdAt"); CREATE INDEX IF NOT EXISTS "FraudSignal_caseId_idx" ON "FraudSignal"("caseId");
ALTER TABLE "Referral" ADD CONSTRAINT "Referral_referrerId_fkey" FOREIGN KEY ("referrerId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
